// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { float32ndarray } from '@stdlib/types/ndarray';

/**
* Performs one of the matrix-vector operations `x = A*x` or `x = A^T*x`, where `x` is an `N` element ndarray and `A` is an `N` by `N` unit, or non-unit, upper or lower triangular matrix.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a two-dimensional input ndarray.
*
* @param arrays - array-like object containing ndarrays
* @returns output ndarray
*
* @example
* var Float32Vector = require( '@stdlib/ndarray/vector/float32' );
* var ndarray = require( '@stdlib/ndarray/base/ctor' );
* var Float32Array = require( '@stdlib/array/float32' );
*
* var x = new Float32Vector( [ 1.0, 2.0, 3.0 ] );
* var A = new ndarray( 'float32', new Float32Array( [ 1.0, 2.0, 3.0, 2.0, 1.0, 2.0, 3.0, 2.0, 1.0 ] ), [ 3, 3 ], [ 3, 1 ], 0, 'row-major' );
*
* var out = strmv( [ x, A ] );
* // returns <ndarray>[ 14.0, 8.0, 3.0 ]
*
* var bool = ( out === x );
* // returns true
*/
declare function strmv( arrays: [ float32ndarray, float32ndarray ] ): float32ndarray;


// EXPORTS //

export = strmv;
